<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();if(es_control())ir('panel.php');if($_SERVER['REQUEST_METHOD']==='POST'){validar_token();$uuid=bin2hex(random_bytes(16));$idD=(int)usuario()['id_distrito'];$uid=(int)usuario()['id_usuario'];$s=bd()->prepare("INSERT INTO casos_actualizacion(uuid_registro,id_distrito,id_usuario_registro,nombre_solicitante,tipo_solicitante,fecha_recepcion,medio_recepcion,descripcion_solicitud,estado,fase_actual,sin_casos) VALUES(?,?,?,'Dirección Distrital','Declaración institucional',CURDATE(),'Sistema','La Dirección Distrital declara que no presenta casos de actualización.','SIN_CASOS',8,1)");$s->bind_param('sii',$uuid,$idD,$uid);$s->execute();$id=$s->insert_id;$f=sprintf('MGPC-2028-DD%02d-SIN-%05d',usuario()['numero_distrito'],$id);$q=bd()->prepare('UPDATE casos_actualizacion SET folio=? WHERE id_caso=?');$q->bind_param('si',$f,$id);$q->execute();ir('acuse_sin_casos.php?id='.$id);}include 'encabezado.php';?><section class="tarjeta"><h1>Registro sin casos de actualización</h1><div class="aviso">Esta opción genera un registro formal y un acuse PDF para la Dirección Distrital.</div><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label><input style="width:auto" type="checkbox" required> Confirmo que el Distrito Local no presenta casos de actualización.</label><button class="boton">Registrar y generar acuse</button></form></section><?php include 'pie.php';?>